1	/**
2	 * The ACL sync orchestrator — ONE scheduled tick that re-materializes every
3	 * registered source's access graph. Each source owns its own fetch (Slack:
4	 * `conversations.members` over agent-connection-bound channels; GitHub: repo
5	 * collaborators over connection feeds) because data acquisition is inherently
6	 * per-source; they all converge on the same `buildAccessGraph` engine + the same
7	 * `authz_source_acl_state` switch the gates read. Adding a source = add its
8	 * `run<Source>AclSyncTick` here.
9	 *
10	 * Error isolation: a source tick that throws is logged and never aborts the
11	 * others (each source's per-connection sync is already atomic/fail-closed).
12	 */
13	
14	import { createLogger } from '@lobu/core';
15	import type { CoreServices } from '../gateway/services/core-services.js';
16	import { runGithubAclSyncTick } from './github-acl-sync.js';
17	import { runSlackAclSyncTick } from './slack-acl-sync.js';
18	
19	const logger = createLogger('acl-sync');
20	
21	export async function runAclSyncTick(coreServices: CoreServices): Promise<void> {
22	  const sources: Array<{ key: string; run: () => Promise<void> }> = [
23	    { key: 'slack', run: () => runSlackAclSyncTick(coreServices) },
24	    { key: 'github', run: () => runGithubAclSyncTick(coreServices) },
25	  ];
26	  for (const source of sources) {
27	    try {
28	      await source.run();
29	    } catch (error) {
30	      logger.error({ source: source.key, error: String(error) }, 'ACL sync source tick failed');
31	    }
32	  }
33	}
