1	/**
2	 * Slack connector identity namespaces and normalization.
3	 *
4	 * Single source of truth for slack_user_id / slack_channel_id rules. The auth
5	 * sign-in path, channel ACL graph, transcript sender resolution, and server
6	 * entity-link ingestion all import from here — not from connector-sdk.
7	 * Connector-specific identity knowledge stays in the connector package so core
8	 * code never names Slack.
9	 */
10	
11	import type {
12	  AccessResource,
13	  AclSourceDef,
14	  ChannelReadIdentity,
15	} from '@lobu/connector-sdk';
16	import type { ConnectorIdentityModule } from './connector-identity-module.js';
17	
18	/** Connector-owned identity namespaces (not SDK-global). */
19	export const SLACK_IDENTITY = {
20	  /** Team-scoped user id `T…:U…` (upper-cased). Bare Slack user ids are unsafe. */
21	  USER_ID: 'slack_user_id',
22	  /** Team-scoped channel id `T…:C…` (upper-cased) — the ACL resource key. */
23	  CHANNEL_ID: 'slack_channel_id',
24	} as const;
25	
26	export type SlackIdentityNamespace =
27	  (typeof SLACK_IDENTITY)[keyof typeof SLACK_IDENTITY];
28	
29	/**
30	 * Slack user IDs aren't globally unique — two workspaces can both have
31	 * `U12345`. Prefix with the workspace (team) id so identities don't bleed
32	 * across orgs: `T0XYZ:U12345` (upper-cased).
33	 */
34	export function normalizeSlackUserId(
35	  teamId: string | null | undefined,
36	  userId: string | null | undefined,
37	): string | null {
38	  if (typeof teamId !== 'string' || typeof userId !== 'string') return null;
39	  const t = teamId.trim();
40	  const u = userId.trim();
41	  if (!t || !u) return null;
42	  if (!/^[a-z0-9_-]+$/i.test(t) || !/^[a-z0-9_-]+$/i.test(u)) return null;
43	  return `${t}:${u}`.toUpperCase();
44	}
45	
46	/**
47	 * Canonicalize an already-combined team-scoped Slack id (`T0XYZ:U12345`).
48	 * Connectors/auth emit the team-prefixed form (build it with
49	 * `normalizeSlackUserId(teamId, userId)`); this is the single-value cleanup
50	 * pass the ingestion pipeline re-runs. Splits on the first colon and re-runs
51	 * the two-part validator so a malformed value (no team prefix, bad chars)
52	 * returns null rather than poisoning matching. Shared by user and channel ids
53	 * (both are `TEAM:ID` shaped).
54	 */
55	function normalizeTeamScopedId(raw: string | null | undefined): string | null {
56	  if (typeof raw !== 'string') return null;
57	  const trimmed = raw.trim();
58	  if (!trimmed) return null;
59	  const sep = trimmed.indexOf(':');
60	  if (sep <= 0 || sep === trimmed.length - 1) return null;
61	  return normalizeSlackUserId(trimmed.slice(0, sep), trimmed.slice(sep + 1));
62	}
63	
64	/**
65	 * Normalize a Slack identity namespace value. Returns `undefined` when the
66	 * namespace is not Slack-owned (caller should fall back to generic hygiene).
67	 */
68	export function normalizeSlackIdentityValue(
69	  namespace: string,
70	  raw: string,
71	): string | null | undefined {
72	  switch (namespace) {
73	    case SLACK_IDENTITY.USER_ID:
74	    case SLACK_IDENTITY.CHANNEL_ID:
75	      return normalizeTeamScopedId(raw);
76	    default:
77	      return undefined;
78	  }
79	}
80	
81	/** The Slack connector's contribution to the server identity wiring. */
82	export const slackIdentityModule: ConnectorIdentityModule = {
83	  key: 'slack',
84	  // slack_user_id is recall-indexed (idx_events_metadata_slack_user_id);
85	  // slack_channel_id is an ACL resource key, not an event-recall namespace.
86	  recallNamespaces: [SLACK_IDENTITY.USER_ID],
87	  normalize: normalizeSlackIdentityValue,
88	};
89	
90	// ── ACL source ────────────────────────────────────────────────────────────
91	//
92	// Slack channel membership is a read ACL: a requester may recall a channel iff
93	// they are `member_of` it. The connector owns how a workspace's channels +
94	// members normalize into the generic engine's resource/audience shape; the
95	// server-side materializer (buildAccessGraph) does the IO.
96	
97	/** The team-scoped channel key the gate matches on (`T…:C…`, upper-cased). */
98	export function slackChannelKey(teamId: string, channelId: string): string {
99	  return `${teamId.trim()}:${channelId.trim()}`.toUpperCase();
100	}
101	
102	/**
103	 * Slack's read-gate identity model — how the per-channel visibility gate keys a
104	 * channel and a requester. The ONE place the gate learns Slack's team-scoped
105	 * `T…:C…` / `T…:U…` shape; the gate itself dispatches on `platform` and names no
106	 * connector. `channelKeySql` reproduces `buildChannelKey`'s construction as a
107	 * SQL expression for the message-visibility compiler (which keys inside a query,
108	 * so it can't call the TS builder). Both must stay byte-identical.
109	 */
110	export const slackChannelReadIdentity: ChannelReadIdentity = {
111	  platform: 'slack',
112	  channelNamespace: SLACK_IDENTITY.CHANNEL_ID,
113	  userNamespace: SLACK_IDENTITY.USER_ID,
114	  buildChannelKey(teamId, bareChannelId) {
115	    if (!teamId || !bareChannelId) return null;
116	    return slackChannelKey(teamId, bareChannelId);
117	  },
118	  buildUserKey(teamId, userId) {
119	    return normalizeSlackUserId(teamId, userId);
120	  },
121	  channelKeySql(teamColExpr, channelColExpr) {
122	    // Mirrors slackChannelKey: UPPER(team || ':' || channel). The team column
123	    // may be a COALESCE the compiler builds; the channel column is the bare id.
124	    return `UPPER(${teamColExpr} || ':' || ${channelColExpr})`;
125	  },
126	};
127	
128	/** A Slack channel and the (bare `U…`) ids of its members. */
129	export interface SlackChannelInput {
130	  /** Bare Slack channel id (`C…` / `G…`). */
131	  channelId: string;
132	  name?: string;
133	  isPrivate?: boolean;
134	  /** Bare Slack user ids (`U…`) of the channel's members. */
135	  memberSlackUserIds: string[];
136	}
137	
138	/** The Slack connector's ACL-source descriptor. */
139	export const slackAclSource: AclSourceDef = {
140	  key: 'slack',
141	  resourceNamespace: SLACK_IDENTITY.CHANNEL_ID,
142	  memberIdentities: [{ namespace: SLACK_IDENTITY.USER_ID, primary: true }],
143	};
144	
145	/**
146	 * Normalize a Slack workspace's channels into engine resources: each channel a
147	 * team-scoped `T…:C…` key; each member resolved on the canonical team-scoped
148	 * `slack_user_id` namespace so a signed-in member collapses onto their entity.
149	 * Channels without an id, and members whose id doesn't team-scope, are dropped.
150	 */
151	export function slackChannelsToResources(
152	  teamId: string,
153	  channels: SlackChannelInput[],
154	): AccessResource[] {
155	  const resources: AccessResource[] = [];
156	  for (const c of channels) {
157	    if (!c.channelId) continue;
158	    const members: AccessResource['members'] = [];
159	    for (const u of c.memberSlackUserIds) {
160	      const combined = normalizeSlackUserId(teamId, u);
161	      if (!combined) continue;
162	      members.push({
163	        key: combined,
164	        name: combined,
165	        identities: [{ namespace: SLACK_IDENTITY.USER_ID, value: combined }],
166	      });
167	    }
168	    resources.push({
169	      key: slackChannelKey(teamId, c.channelId),
170	      name: c.name ?? c.channelId,
171	      members,
172	    });
173	  }
174	  return resources;
175	}
