1	/**
2	 * Slack channel-membership SYNC — the production path that populates the authz
3	 * graph the visibility gate reads. Without this, `buildSlackChannelGraph` would
4	 * only ever run from tests and the gate would never enforce a real connection.
5	 *
6	 * Per Slack connection: resolve the channels it actually captures
7	 * (`resolveBoundChannelRows` — the same source of truth the gate filters), fetch
8	 * each channel's current membership from Slack (`conversations.members`), and
9	 * hand the whole set to `buildSlackChannelGraph`, which materializes the
10	 * `member_of` edges, reconciles departures, and stamps the connection
11	 * `full`/`fresh`. A periodic tick (`runSlackAclSyncTick`, wired in
12	 * `scheduled/jobs.ts`) re-runs this so membership changes (joins/leaves) converge
13	 * within the sync cadence, and the gate's freshness window fails the connection
14	 * closed if the tick ever stops.
15	 *
16	 * Fail-closed on error: the sync is ATOMIC per connection. If ANY channel's
17	 * membership fetch throws (Slack outage, bot removed, missing token), we do NOT
18	 * build a half-synced graph — we mark the connection's ACL state `failed` so the
19	 * gate drops all its channels until a later tick succeeds. We only DOWNGRADE an
20	 * existing row; a connection that has never been graphed stays on the legacy
21	 * fence (a brand-new connection whose first sync fails must not suddenly hide
22	 * every channel).
23	 */
24	
25	import { createLogger } from '@lobu/core';
26	import { getDb } from '../db/client.js';
27	import {
28	  resolveBoundChannelRows,
29	  stripPlatformPrefix,
30	} from '../gateway/channels/bound-channels.js';
31	import { createSlackWebApi, type SlackWebApi } from '../gateway/connections/slack-web.js';
32	import { resolveSecretValue } from '../gateway/secrets/index.js';
33	import type { SecretStore } from '../gateway/secrets/index.js';
34	import type { CoreServices } from '../gateway/services/core-services.js';
35	import {
36	  runtimeConnectionIdToSlug,
37	  slugToRuntimeConnectionId,
38	} from '../lobu/stores/connections-projection.js';
39	import {
40	  getSlackInstallById,
41	  getSlackInstallByTeamId,
42	} from '../lobu/stores/slack-installations.js';
43	import { orgContext } from '../lobu/stores/org-context.js';
44	import {
45	  type SlackChannelInput,
46	  slackAclSource,
47	  slackChannelsToResources,
48	} from '@lobu/connectors/slack-identity';
49	import { buildAccessGraph } from './access-graph.js';
50	
51	const logger = createLogger('slack-acl-sync');
52	
53	/** Injectable seams so tests drive the real graph build + gate with a stubbed
54	 * Slack API and token resolver, and the live tick wires the real ones. */
55	export interface SlackAclSyncDeps {
56	  slackWeb: Pick<SlackWebApi, 'conversationMembers' | 'conversationInfo'>;
57	  /**
58	   * Resolve the bot IDENTITY for a workspace — its token plus the bot's own
59	   * Slack user id — or null if none is available (no active install AND no BYO
60	   * token / unresolvable secret), which is treated fail-closed. The OAuth-install
61	   * path sources the bot id from the install (stamped at install time). The BYO
62	   * fallback sources it from the connection's `chatMetadata.botUserId`, which is
63	   * backfilled lazily at adapter init: if it is still null (pre-first-run window)
64	   * the bot is NOT filtered out and can transiently gain a `member_of` edge —
65	   * self-healing on the next sync once the id backfills (a bot id maps to no
66	   * human requester, so this is audience inflation, never access leakage).
67	   */
68	  resolveBotIdentity: (params: {
69	    organizationId: string;
70	    teamId: string;
71	    /**
72	     * The connection being synced. Lets the resolver fall back to the
73	     * connection's own BYO bot credentials when the team has no OAuth
74	     * app-installation — otherwise a BYO Slack connection (active bot, real
75	     * bindings, no install row) never gets ACL-graphed and its channel memory
76	     * silently degrades to org scope.
77	     */
78	    connectionId: string;
79	  }) => Promise<{ token: string; botUserId: string | null } | null>;
80	}
81	
82	export interface SlackAclSyncResult {
83	  /** True when every bound Slack channel was fetched and graphed. */
84	  ok: boolean;
85	  teamsSynced: number;
86	  channelsSynced: number;
87	}
88	
89	/** Downgrade an EXISTING ACL row to `failed` so the gate fails closed. A no-op
90	 * when the connection was never graphed (no row) — it stays on the legacy
91	 * fence rather than flipping to drop-everything on its first failure. */
92	async function markConnectionAclFailed(
93	  organizationId: string,
94	  connectionId: string,
95	): Promise<void> {
96	  const sql = getDb();
97	  await sql`
98			UPDATE authz_source_acl_state
99			SET freshness_state = 'failed', updated_at = current_timestamp
100			WHERE organization_id = ${organizationId}
101			  AND connection_id = ${connectionId}
102		`;
103	}
104	
105	/**
106	 * Sync ONE Slack connection's channel-membership graph. Resolves its captured
107	 * channels, fetches members per channel, and builds the graph (per team). See
108	 * the file header for the fail-closed contract.
109	 */
110	export async function syncSlackConnectionAcl(
111	  deps: SlackAclSyncDeps,
112	  params: { connectionId: string; organizationId: string },
113	): Promise<SlackAclSyncResult> {
114	  const { connectionId, organizationId } = params;
115	  const sql = getDb();
116	
117	  const bound = await resolveBoundChannelRows(sql, {
118	    organizationId,
119	    connectionId,
120	  });
121	
122	  // `resolveBoundChannelRows` narrows bindings to THIS connection (by slug), so
123	  // every row here already belongs to it — we trust connection_id as the scope,
124	  // NOT a team-string round-trip. `connTeamId` is only used to guard the BYO
125	  // multi-workspace case: when the connection's tenant id is itself a WORKSPACE
126	  // (`T…`), a binding for a DIFFERENT workspace is a stray second-connection row
127	  // and is dropped (fetched with the wrong token → fail-closed otherwise). When
128	  // the tenant id is NOT a workspace — a Grid ENTERPRISE (`E…`) org-wide install,
129	  // whose bindings correctly carry the sibling workspace `T…`, or a preview
130	  // connection (no teamId) — we accept EVERY real-team binding on the connection
131	  // and group by the binding's own team. Without this relaxation an org-wide
132	  // install (connTeamId = E…) drops all its `T…` bindings and silently
133	  // downgrades to the legacy per-agent fence.
134	  const [conn] = await sql<{ team_id: string | null }>`
135			SELECT COALESCE(external_tenant_id, config->'chatMetadata'->>'teamId') AS team_id
136			FROM connections
137			WHERE slug = ${runtimeConnectionIdToSlug(connectionId)}
138			  AND organization_id = ${organizationId}
139			  AND credential_mode IS NOT NULL
140			  AND deleted_at IS NULL
141			LIMIT 1
142		`;
143	  const connTeamId = conn?.team_id ?? null;
144	  // Is the connection's tenant id itself a concrete workspace? Only then do we
145	  // enforce workspace equality (BYO foreign-workspace guard). An enterprise `E…`
146	  // or absent tenant id does NOT constrain the binding team.
147	  const connScopesWorkspace = /^T[A-Z0-9]+$/i.test(connTeamId ?? '');
148	
149	  // Only Slack rows that carry a real workspace team can be team-scoped into the
150	  // graph; a channel with no team id is dropped fail-closed by the gate anyway.
151	  const slackRows = bound.filter(
152	    (r) =>
153	      r.platform.startsWith('slack') &&
154	      r.team_id &&
155	      (!connScopesWorkspace || r.team_id === connTeamId),
156	  );
157	  if (slackRows.length === 0) {
158	    return { ok: true, teamsSynced: 0, channelsSynced: 0 };
159	  }
160	
161	  // Group channels by workspace/team — one graph build per team.
162	  const byTeam = new Map<string, string[]>();
163	  for (const r of slackRows) {
164	    const channelId = stripPlatformPrefix(r.platform, r.channel_id);
165	    const list = byTeam.get(r.team_id as string) ?? [];
166	    list.push(channelId);
167	    byTeam.set(r.team_id as string, list);
168	  }
169	
170	  let teamsSynced = 0;
171	  let channelsSynced = 0;
172	  try {
173	    for (const [teamId, channelIds] of byTeam) {
174	      const identity = await deps.resolveBotIdentity({ organizationId, teamId, connectionId });
175	      if (!identity) {
176	        throw new Error(`No bot token for team ${teamId}`);
177	      }
178	      const { token, botUserId } = identity;
179	      const channels: SlackChannelInput[] = [];
180	      for (const channelId of channelIds) {
181	        // Per-channel tolerance for a STALE binding: if the bot was kicked, the
182	        // channel was archived/deleted, or it's simply not in it, Slack throws
183	        // `channel_not_found` / `not_in_channel` / `is_archived`. That channel
184	        // has no readable audience — DROP it from the graph and keep going;
185	        // fail-closing the whole connection over one dead binding would ungraph
186	        // every OTHER (readable) channel too. Systemic errors (auth, rate limit)
187	        // still propagate to the outer catch and fail the connection closed.
188	        let rawMembers: string[];
189	        try {
190	          rawMembers = await deps.slackWeb.conversationMembers(token, channelId);
191	        } catch (error) {
192	          const msg = String(error);
193	          if (
194	            /channel_not_found|not_in_channel|is_archived|method_not_supported_for_channel_type/.test(
195	              msg,
196	            )
197	          ) {
198	            // Definitively unreadable (bot kicked / channel archived/gone),
199	            // NOT transient. Push it with an EMPTY member set so graph
200	            // reconciliation soft-deletes its stale `member_of` edges (revokes
201	            // recall) — skipping would leave them alive (fail-OPEN). Transient
202	            // errors (ratelimit/auth) fall through to `throw` → whole connection
203	            // fails closed, so we never wipe edges on a flaky fetch.
204	            logger.warn(
205	              { organization_id: organizationId, channel_id: channelId, error: msg },
206	              'Slack conversations.members: channel unreadable (stale binding) — reconciling to no members',
207	            );
208	            channels.push({ channelId, memberSlackUserIds: [] });
209	            continue;
210	          }
211	          throw error;
212	        }
213	        // The bot is itself a member of every channel it's in, so
214	        // `conversations.members` includes it. Drop it: a bot is not an audience
215	        // and must never gain a `member_of` edge (it would inflate "who can
216	        // recall" AND, via the gate, count as a member). The bot id is the
217	        // install's, scoped to THIS team. Absent it, we don't filter (no regression).
218	        const memberSlackUserIds = botUserId
219	          ? rawMembers.filter((u) => u !== botUserId)
220	          : rawMembers;
221	        // Channel name + privacy are BEST-EFFORT display metadata — a failure
222	        // here must NOT fail-close the whole sync (membership is the contract),
223	        // so swallow and fall back to the id-as-name in buildSlackChannelGraph.
224	        let name: string | undefined;
225	        let isPrivate: boolean | undefined;
226	        try {
227	          const info = await deps.slackWeb.conversationInfo(token, channelId);
228	          name = info.name ?? undefined;
229	          isPrivate = info.isPrivate;
230	        } catch (error) {
231	          logger.warn(
232	            { organization_id: organizationId, channel_id: channelId, error: String(error) },
233	            'Slack conversations.info failed — syncing channel without a name',
234	          );
235	        }
236	        channels.push({ channelId, name, isPrivate, memberSlackUserIds });
237	      }
238	      await buildAccessGraph({
239	        organizationId,
240	        connectionId,
241	        connectorKey: slackAclSource.key,
242	        resourceNamespace: slackAclSource.resourceNamespace,
243	        memberIdentities: slackAclSource.memberIdentities,
244	        resources: slackChannelsToResources(teamId, channels),
245	      });
246	      teamsSynced += 1;
247	      channelsSynced += channels.length;
248	    }
249	    return { ok: true, teamsSynced, channelsSynced };
250	  } catch (error) {
251	    logger.error(
252	      {
253	        organization_id: organizationId,
254	        connection_id: connectionId,
255	        error: String(error),
256	      },
257	      'Slack ACL sync failed — marking connection fail-closed',
258	    );
259	    await markConnectionAclFailed(organizationId, connectionId);
260	    return { ok: false, teamsSynced, channelsSynced };
261	  }
262	}
263	
264	/**
265	 * Resolve the bot token + user id for one Slack connection's ACL sync. Prefers
266	 * the workspace OAuth app-installation (hosted/managed path); falls back to the
267	 * connection's OWN bot credentials for a BYO Slack connection that has no
268	 * install row. Exported so both branches are unit-testable — the BYO fallback
269	 * is what lets an active-but-BYO connection (real bindings, no install) actually
270	 * graph instead of failing closed and silently degrading channel memory to org
271	 * scope.
272	 */
273	export async function resolveSlackBotIdentity(
274	  deps: {
275	    installStore: ReturnType<CoreServices['getAppInstallationStore']>;
276	    // Only the read side (`.get`) is used, via resolveSecretValue — accept the
277	    // minimal SecretStore so callers with either the WritableSecretStore
278	    // (platform.ts CoreServices) or the SecretStoreRegistry (concrete) type fit.
279	    secretStore: SecretStore;
280	    slackWeb: SlackWebApi;
281	  },
282	  params: { organizationId: string; teamId: string; connectionId: string },
283	): Promise<{ token: string; botUserId: string | null } | null> {
284	  const { installStore, secretStore, slackWeb } = deps;
285	  const { organizationId, teamId, connectionId } = params;
286	
287	  // Primary: resolve the install by THIS connection's concrete id
288	  // (`slackinst-<uuid>` slug = the install external id), NOT by round-tripping
289	  // the team string. On a Grid ORG-WIDE install the install row is keyed on the
290	  // ENTERPRISE id, so a per-team `getSlackInstallByTeamId(T…)` lookup misses for
291	  // every sibling workspace — but the one bot token is enterprise-wide and reads
292	  // every workspace's channels. Resolving by connection id gives us that token
293	  // for any `T…` we're graphing. Only slackinst- slugs are installs; a BYO slug
294	  // (`agentconn-…`) skips straight to the fallback below.
295	  const connSlug = runtimeConnectionIdToSlug(connectionId);
296	  const installById = connSlug.startsWith('slackinst-')
297	    ? await getSlackInstallById(installStore, connSlug)
298	    : null;
299	  if (installById && installById.status === 'active') {
300	    const tokenRef = (installById.config as { botToken?: string }).botToken;
301	    const token = await orgContext.run(
302	      { organizationId: installById.organizationId },
303	      () => resolveSecretValue(secretStore, tokenRef),
304	    );
305	    if (token) return { token, botUserId: installById.botUserId ?? null };
306	  }
307	
308	  // Secondary: the workspace OAuth app-installation keyed by team (a normal,
309	  // non-org-wide install whose connection slug may not be the install id).
310	  const install = await getSlackInstallByTeamId(installStore, teamId);
311	  if (install && install.status === 'active') {
312	    const tokenRef = (install.config as { botToken?: string }).botToken;
313	    const token = await orgContext.run({ organizationId: install.organizationId }, () =>
314	      resolveSecretValue(secretStore, tokenRef),
315	    );
316	    if (token) return { token, botUserId: install.botUserId ?? null };
317	  }
318	
319	  // Fallback: a BYO Slack connection has no install row — its bot token + user
320	  // id live on the connection's own config. The token is a `secret://` ref,
321	  // resolved under the connection's org exactly like the install path.
322	  //
323	  // We fetch by (slug, org) only and check the team OURSELVES rather than in the
324	  // predicate: a BYO connection created without an OAuth install NEVER persists a
325	  // teamId (see slack-connection-coordinator: "created without an OAuth install
326	  // never gets a metadata.teamId"), so a `= ${teamId}` predicate would drop it
327	  // entirely and the sync would fail closed forever. Instead we self-heal.
328	  const sql = getDb();
329	  const [conn] = await sql<{
330	    organization_id: string;
331	    // Slack connection config stores botToken at the top level (the
332	    // OAuth-install writer's shape); COALESCE the chatMetadata nesting too.
333	    bot_token_ref: string | null;
334	    bot_user_id: string | null;
335	    // The team this connection is already known to belong to, if any.
336	    stored_team_id: string | null;
337	  }>`
338			SELECT organization_id,
339			       COALESCE(config->>'botToken', config->'chatMetadata'->>'botToken') AS bot_token_ref,
340			       config->'chatMetadata'->>'botUserId' AS bot_user_id,
341			       COALESCE(external_tenant_id, config->'chatMetadata'->>'teamId') AS stored_team_id
342			FROM connections
343			WHERE slug = ${runtimeConnectionIdToSlug(connectionId)}
344			  AND organization_id = ${organizationId}
345			  AND connector_key = 'slack'
346			  AND status = 'active'
